local function clean(text)
    return (tostring(text or ""):gsub("<[^>]*>", ""):gsub("%s+", ""))
end
local words, seen, buckets = {}, {}, {}
for word in WORDS_TEXT:gmatch("[^\r\n]+") do
    word = clean(word)
    if word ~= "" and not seen[word] then
        seen[word] = true
        table.insert(words, word)
        local key = word:sub(1, 3) -- first Thai codepoint; vocabulary is Thai-only
        buckets[key] = buckets[key] or {}
        table.insert(buckets[key], word)
    end
end
local function letterLength(word)
    local n = 0
    for _, cp in utf8.codes(word) do
        -- Count visible base letters conservatively; combining marks add no length.
        if cp ~= 0x0E31 and not (cp >= 0x0E34 and cp <= 0x0E3A)
            and not (cp >= 0x0E47 and cp <= 0x0E4E) then n = n + 1 end
    end
    return n
end
local function detectMinimum(text)
    text = tostring(text or ""):gsub("<[^>]*>", "")
    local n = tonumber(text:match("ยาว%s*(%d+)%s*ตัว"))
    return n and math.max(1, math.min(n, 32)) or 1
end
-- Reported to fail repeatedly in the game; retain across match/reset history.
local blockedWords = {["งงงวย"]=true, ["งงวย"]=true}
local function selectWord(prefix, used, minimum)
    if prefix == "" then return nil end
    for _, word in ipairs(buckets[prefix:sub(1, 3)] or {}) do
        if not blockedWords[word] and not used[word] and #word > #prefix and word:sub(1, #prefix) == prefix
            and letterLength(word) >= (minimum or 1) then
            return word
        end
    end
end
local function inputText(word, prefix, suffixOnly)
    -- UTF-8 byte slicing is valid here because prefix is an exact full-string prefix.
    return suffixOnly and word:sub(#prefix + 1) or word
end

